import { useState, useSyncExternalStore } from "react";

/* Example dates count from when they appear. An app takes its dates from its data. */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** A fixed moment for server rendering, so the server and the browser write the same HTML. */
const reference = Date.UTC(2026, 0, 15, 12);

const subscribe = () => () => {
  // Whether the page has hydrated never changes back.
};

const useDemoClock = () => {
  // oxlint-disable-next-line react/hook-use-state -- the time is read once, when the example appears, and never replaced.
  const [appeared] = useState(() => Date.now());

  return useSyncExternalStore(
    subscribe,
    () => appeared,
    () => reference,
  );
};

export { DAY, HOUR, MINUTE, useDemoClock };

import { CopyButton, CopyButtonIcon, CopyButtonLabel } from "@/registry/erbium/blocks/copy-button";
import { Button } from "@/registry/erbium/ui/button";
import {
  RelativeTime,
  RelativeTimeCard,
  RelativeTimeCardContent,
  RelativeTimeCardTitle,
  RelativeTimeCardTrigger,
  RelativeTimeZone,
  RelativeTimeZoneList,
} from "@/registry/erbium/ui/relative-time";
import { DAY, useDemoClock } from "../examples/use-demo-clock";

export default function RelativeTimeCardZonesExample() {
  const date = new Date(useDemoClock() + 2 * DAY);

  return (
    <RelativeTimeCard date={date} locale="en">
      <RelativeTimeCardTrigger render={<Button variant="outline" />}>
        Launch <RelativeTime />
      </RelativeTimeCardTrigger>
      <RelativeTimeCardContent>
        <RelativeTimeCardTitle />
        <RelativeTimeZoneList>
          <RelativeTimeZone hideIfSameAs={["Europe/London", "Asia/Tehran", "Asia/Tokyo"]} />
          <RelativeTimeZone timeZone="Europe/London" label="London" />
          <RelativeTimeZone timeZone="Asia/Tehran" label="Tehran" />
          <RelativeTimeZone timeZone="Asia/Tokyo" label="Tokyo" />
        </RelativeTimeZoneList>
        <CopyButton value={date.toISOString()} size="sm" variant="outline">
          <CopyButtonIcon data-icon="inline-start" />
          <CopyButtonLabel>Copy ISO time</CopyButtonLabel>
        </CopyButton>
      </RelativeTimeCardContent>
    </RelativeTimeCard>
  );
}
